import unittest
from candidate import get_positive

class TestGetPositive(unittest.TestCase):
    def test_normal_case_mixed_values(self):
        self.assertEqual(get_positive([-1, 2, -4, 5, 6]), [2, 5, 6])

    def test_all_positives(self):
        self.assertEqual(get_positive([1, 2, 3, 4]), [1, 2, 3, 4])

    def test_all_negatives(self):
        self.assertEqual(get_positive([-1, -2, -3]), [])

    def test_contains_zero(self):
        self.assertEqual(get_positive([0, -5, 5]), [5])

    def test_empty_list_input(self):
        self.assertEqual(get_positive([]), [])

    def test_single_positive_element(self):
        self.assertEqual(get_positive([42]), [42])

    def test_single_negative_element(self):
        self.assertEqual(get_positive([-10]), [])

    def test_single_zero_element(self):
        self.assertEqual(get_positive([0]), [])

    def test_large_list_with_many_elements(self):
        input_list = list(range(-5, 6))
        expected = [x for x in range(-5, 6) if x > 0]
        self.assertEqual(get_positive(input_list), expected)

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            get_positive(None)

    def test_string_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            get_positive("abc")

    def test_float_values_filtered_correctly(self):
        self.assertEqual(get_positive([-1.5, 2.0, 0.5, -3.2]), [2.0, 0.5])

    def test_duplicates_preserved(self):
        self.assertEqual(get_positive([1, 2, 2, 3, -1]), [1, 2, 2, 3])
